def metric(df: pd.DataFrame) -> float:
    import numpy as np
    import pandas as pd

    # Exclude rows where actual is zero to avoid division by zero
    valid = df[df['actual'] != 0].copy()

    if len(valid) == 0:
        return float('nan')

    ape = np.abs(valid['actual'] - valid['forecast']) / np.abs(valid['actual'])
    mape = float(ape.mean() * 100)
    return mape
